mapper.select:
WITH hnsw_config AS (
    SELECT set_config('hnsw.iterative_scan', 'relaxed_order', true),
           set_config('hnsw.ef_search', #{efSearch}::text, true)
)
SELECT id, library_id, media_id, content, embedding, chunk_index, metadata, created_at,
       1 - (embedding <=> #{queryEmbedding}::vector) AS similarity
FROM kb_chunk, hnsw_config
WHERE library_id = #{libraryId}
ORDER BY embedding <=> #{queryEmbedding}::vector
LIMIT #{topK}

SELECT id, library_id, media_id, content, chunk_index, metadata, created_at, ts_rank_cd(to_tsvector('simple', content), plainto_tsquery('simple', #{queryTerms})) AS bm25_score FROM kb_chunk
library_id = #{libraryId}
AND to_tsvector('simple', content) @@ plainto_tsquery('simple', #{queryTerms})
ORDER BY bm25_score DESC LIMIT #{topK}
